use crate::launcher::{base_data_dir, download_to, Progress, VersionMeta};
use regex::Regex;
use std::{fs, io, path::{Path,PathBuf}, process::Command};
use walkdir::WalkDir;
use zip::ZipArchive;

pub fn required_java_major(meta:&VersionMeta)->i32{if meta.java_version.major_version>0{meta.java_version.major_version}else{8}}
pub fn ensure_java(required:i32,progress:Option<Progress<'_>>)->Result<PathBuf,String>{if let Some(p)=progress{p(format!("Java {required} aranıyor…"),0.82)}let mut seen=std::collections::HashSet::new();for c in java_candidates(required){let k=c.to_string_lossy().to_ascii_lowercase();if !seen.insert(k){continue}let major=java_major(&c);if java_compatible(required,major){if let Some(p)=progress{p(format!("Java {major} hazır."),0.86)}return Ok(prefer_javaw(&c));}}
    if let Some(p)=progress{p(format!("Java {required} otomatik indiriliyor…"),0.84)}match download_java_runtime(required,progress){Ok(p)=>Ok(p),Err(e) if required==16=>{if let Some(p)=progress{p("Java 16 bulunamadı; Java 17 deneniyor…".into(),0.84)}download_java_runtime(17,progress).map_err(|e2|format!("Java 16/17 indirilemedi: {e}; {e2}"))},Err(e)=>Err(format!("Java {required} bulunamadı ve otomatik indirme başarısız: {e}"))}}
fn java_compatible(r:i32,a:i32)->bool{match r{8=>a==8,16=>a==16||a==17,17=>a==17,21=>(21..25).contains(&a),_=>a==r}}
fn java_candidates(required:i32)->Vec<PathBuf>{let mut out=vec![];collect_java(&mut out,&base_data_dir().join("runtimes").join(format!("java{required}")),4);if required==16{collect_java(&mut out,&base_data_dir().join("runtimes/java17"),4)}if let Ok(app)=std::env::var("APPDATA"){collect_java(&mut out,&PathBuf::from(app).join(".minecraft/runtime"),7)}if let Ok(h)=std::env::var("JAVA_HOME"){out.push(PathBuf::from(&h).join("bin/javaw.exe"));out.push(PathBuf::from(h).join("bin/java.exe"))}if let Some(path)=std::env::var_os("PATH"){for d in std::env::split_paths(&path){out.push(d.join("javaw.exe"));out.push(d.join("java.exe"));}}out}
fn collect_java(out:&mut Vec<PathBuf>,root:&Path,max_depth:usize){if !root.is_dir(){return}for e in WalkDir::new(root).max_depth(max_depth+1).into_iter().filter_map(Result::ok){if e.file_type().is_file(){let n=e.file_name().to_string_lossy();if (n.eq_ignore_ascii_case("javaw.exe")||n.eq_ignore_ascii_case("java.exe"))&&e.path().parent().and_then(|p|p.file_name()).map(|x|x.to_string_lossy().eq_ignore_ascii_case("bin")).unwrap_or(false){out.push(e.path().to_path_buf())}}}}
fn java_major(path:&Path)->i32{if !path.exists(){return 0}let exe=java_console_path(path);let mut cmd=Command::new(exe);cmd.arg("-version");hide_console(&mut cmd);let Ok(o)=cmd.output()else{return 0};let mut b=o.stderr;b.extend_from_slice(&o.stdout);parse_java_major(&String::from_utf8_lossy(&b))}
fn parse_java_major(s:&str)->i32{let re=Regex::new(r#"version\s+\"([0-9]+)(?:\.([0-9]+))?\""#).unwrap();let Some(c)=re.captures(s)else{return 0};let first=c[1].parse().unwrap_or(0);if first==1{c.get(2).and_then(|m|m.as_str().parse().ok()).unwrap_or(0)}else{first}}
fn prefer_javaw(path:&Path)->PathBuf{if path.file_name().map(|x|x.to_string_lossy().eq_ignore_ascii_case("javaw.exe")).unwrap_or(false){return path.into()}let w=path.parent().unwrap_or(Path::new("")).join("javaw.exe");if w.exists(){w}else{path.into()}}
pub fn java_console_path(path:&Path)->PathBuf{if path.file_name().map(|x|x.to_string_lossy().eq_ignore_ascii_case("javaw.exe")).unwrap_or(false){let p=path.parent().unwrap_or(Path::new("")).join("java.exe");if p.exists(){return p}}path.into()}
fn download_java_runtime(major:i32,progress:Option<Progress<'_>>)->Result<PathBuf,String>{let root=base_data_dir().join("runtimes").join(format!("java{major}"));if let Some(p)=find_java_under(&root){if java_compatible(major,java_major(&p)){return Ok(prefer_javaw(&p))}}let _=fs::remove_dir_all(&root);fs::create_dir_all(&root).map_err(|e|e.to_string())?;let archive=base_data_dir().join("runtimes").join(format!("java{major}.zip"));let urls=[format!("https://api.adoptium.net/v3/binary/latest/{major}/ga/windows/x64/jre/hotspot/normal/eclipse?project=jdk"),format!("https://api.adoptium.net/v3/binary/latest/{major}/ga/windows/x64/jdk/hotspot/normal/eclipse?project=jdk")];let mut last="Java indirilemedi".to_string();for u in urls{let _=fs::remove_file(&archive);let cb=|done:i64,total:i64|if let Some(p)=progress{if total>0{p(format!("Java {major} indiriliyor… {}%",done*100/total),0.84+0.08*done as f64/total as f64)}else{p(format!("Java {major} indiriliyor…"),0.87)}};if let Err(e)=download_to(&u,&archive,"",0,false,Some(&cb)){last=e;continue}if let Err(e)=extract_zip(&archive,&root){last=e;continue}if let Some(p)=find_java_under(&root){let _=fs::remove_file(&archive);let a=java_major(&p);if java_compatible(major,a)||a==major{if let Some(cb)=progress{cb(format!("Java {a} kuruldu."),0.92)}return Ok(prefer_javaw(&p))}last="indirilen Java sürümü uyumsuz".into()}else{last="javaw.exe arşivde bulunamadı".into()}}Err(last)}
fn find_java_under(root:&Path)->Option<PathBuf>{let mut v=vec![];collect_java(&mut v,root,6);v.sort_by_key(|p|(!p.file_name().map(|x|x.to_string_lossy().eq_ignore_ascii_case("javaw.exe")).unwrap_or(false),p.to_string_lossy().len()));v.into_iter().next()}
fn extract_zip(path:&Path,dst:&Path)->Result<(),String>{let f=fs::File::open(path).map_err(|e|e.to_string())?;let mut z=ZipArchive::new(f).map_err(|e|e.to_string())?;for i in 0..z.len(){let mut e=z.by_index(i).map_err(|e|e.to_string())?;let Some(name)=e.enclosed_name().map(|x|x.to_path_buf())else{continue};let target=dst.join(name);if e.is_dir(){fs::create_dir_all(&target).map_err(|e|e.to_string())?;continue}if let Some(p)=target.parent(){fs::create_dir_all(p).map_err(|e|e.to_string())?}let mut out=fs::File::create(target).map_err(|e|e.to_string())?;io::copy(&mut e,&mut out).map_err(|e|e.to_string())?;}Ok(())}
#[cfg(windows)] fn hide_console(cmd:&mut Command){use std::os::windows::process::CommandExt;cmd.creation_flags(0x08000000);}
#[cfg(not(windows))] fn hide_console(_cmd:&mut Command){}
